class Solution {
public:
    int findWinningPlayer(vector<int>& skills, int k) {
        deque<int> q;
        for (int i = 0; i < (int)skills.size(); i++) q.push_back(i);
        int champ = q.front(); q.pop_front();
        int streak = 0;
        while (true) {
            int ch = q.front(); q.pop_front();
            if (skills[champ] > skills[ch]) { streak++; q.push_back(ch); }
            else { q.push_back(champ); champ = ch; streak = 1; }
            if (streak >= k) return champ;
        }
    }
};

