class Solution {
    public int findWinningPlayer(int[] skills, int k) {
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < skills.length; i++) q.addLast(i);
        int champ = q.pollFirst(), streak = 0;
        while (true) {
            int ch = q.pollFirst();
            if (skills[champ] > skills[ch]) { streak++; q.addLast(ch); }
            else { q.addLast(champ); champ = ch; streak = 1; }
            if (streak >= k) return champ;
        }
    }
}

